 test("scene wheel changes orbit-derived lod", async ({ page }) => {
 	await page.goto("/");
 	const canvas = page.locator("canvas").first();
 	await canvas.waitFor({ state: "visible", timeout: 120_000 });
@@
 	await expect
 		.poll(async () => page.locator("[data-scene-root]").getAttribute("data-scene-lod"), { timeout: 30_000 })
 		.not.toBe(before);
 });
+
+test("scene canvas receives native wheel and pointer events", async ({ page }) => {
+	await page.goto("/");
+	const canvas = page.locator("canvas").first();
+	await canvas.waitFor({ state: "visible", timeout: 120_000 });
+	await page.waitForLoadState("networkidle");
+	await canvas.evaluate((el) => {
+		const target = el as HTMLCanvasElement & {
+			__sceneProbe?: { wheel: number; pointerdown: number; pointermove: number; pointerup: number };
+		};
+		target.__sceneProbe = { wheel: 0, pointerdown: 0, pointermove: 0, pointerup: 0 };
+		target.addEventListener("wheel", () => target.__sceneProbe && (target.__sceneProbe.wheel += 1));
+		target.addEventListener("pointerdown", () => target.__sceneProbe && (target.__sceneProbe.pointerdown += 1));
+		target.addEventListener("pointermove", () => target.__sceneProbe && (target.__sceneProbe.pointermove += 1));
+		target.addEventListener("pointerup", () => target.__sceneProbe && (target.__sceneProbe.pointerup += 1));
+	});
+	const box = await canvas.boundingBox();
+	expect(box).not.toBeNull();
+	const x = box!.x + 320;
+	const y = box!.y + 240;
+	await page.mouse.move(x, y);
+	await page.mouse.wheel(0, -600);
+	await page.mouse.down({ button: "right" });
+	await page.mouse.move(x + 40, y + 20, { steps: 4 });
+	await page.mouse.up({ button: "right" });
+	const counts = await canvas.evaluate((el) => {
+		const target = el as HTMLCanvasElement & {
+			__sceneProbe?: { wheel: number; pointerdown: number; pointermove: number; pointerup: number };
+		};
+		return target.__sceneProbe ?? null;
+	});
+	expect(counts).not.toBeNull();
+	expect(counts?.wheel ?? 0).toBeGreaterThan(0);
+	expect(counts?.pointerdown ?? 0).toBeGreaterThan(0);
+	expect(counts?.pointermove ?? 0).toBeGreaterThan(0);
+	expect(counts?.pointerup ?? 0).toBeGreaterThan(0);
+});

